// === Tab: mySketch ===
let d=0
// let colors=["#E715B4","#d90368","#eadeda","#E19B75","#ffd400"]
let colors=["#caa8f5", "#9984d4", "#592e83", "#230c33"]

// let colors = ["#f94144","#f3722c","#f8961e","#f9844a","#f9c74f","#90be6d","#43aa8b","#4d908e","#577590","#277da1",]
let ripples=[]
let drops=[]

function calculateStrokeWeight(d) {
  return map(d, 6, height * 6, 2, 1);
}


function setup() {
  createCanvas(windowWidth, windowHeight);
  strokeWeight(1)
}

function draw() {

  background(0);
  if(frameCount%20==1){
    drops.push(new drop())
  }



  for(let ripple of ripples){
    ripple.update();
    ripple.display();
		ripple.fade();
  }

  for(let drop of drops){
    drop.update();
    drop.display();
  }
}

class ripple {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.d = 10;
    this.color = color;
    this.alpha = 255;
  }

  update() {
    this.d += 5;
    if (this.d > height * 10) {
      let index = ripples.indexOf(this);
      ripples.splice(index, 1);
    }
  }

  display() {
    noFill();
    let strokeColor = color(this.color);
    strokeColor.setAlpha(this.alpha);
		strokeWeight(calculateStrokeWeight(this.d));
    stroke(strokeColor);

    let fillColor = color(this.color);
    fillColor.setAlpha(this.alpha);
    fill(fillColor);

    push();
    translate(this.x, this.y);
    for (let i = 0; i < 30; i++) {
			noFill();


      ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/17, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/17, this.d, this.d / 2);
      rotate(500 + this.d/2000);
    }
    pop();
  }

  fade() {
    if (this.d > 200) {
      // calculate alpha value based on the ripple's current width
      this.alpha = lerp(this.alpha, 0, 0.05);
      if (this.alpha < -10) {
        var index = ripples.indexOf(this);
        ripples.splice(index, 1);
      }
    }
  }
}





class drop{
  constructor(){
    this.x=width/2
    this.y=-5
    this.yacc= 0.2
    this.yvel=0
    this.color= random(colors)
  }
  update(){
    this.yvel+=this.yacc
    this.y+=this.yvel

    if(this.y>=height/2){
     ripples.push(new ripple(width/2, height/2, this.color))
      var index = drops.indexOf(this);
      drops.splice(index, 1);
    }

  }

  display(){

    stroke('white')
    fill(this.color)
   ellipse(this.x, this.y, 18, 20) 
  }
}

